mapper.select:
SELECT p.project_id AS projectId, p.name AS projectName, p.client_name AS clientName, e.name AS projectManager, agg.total_planned_amount AS totalPlannedAmount, COALESCE(agg.total_outcome, 0) AS totalOutcome, COALESCE(agg.total_income, 0) AS totalIncome, COALESCE(agg.completed_round_count, 0) AS completedRoundCount, COALESCE(agg.total_round_count, 0) AS totalRoundCount, COALESCE(agg.pending_round_count, 0) AS pendingRoundCount, nxt.planned_date AS nextPlannedDate, p.status AS projectStatus, p.ended_on AS endedOn FROM project p JOIN employee e ON e.user_id = p.created_by LEFT JOIN ( SELECT st.project_id AS project_id, MAX(CASE WHEN sb.type = 'INCOME' THEN sb.total_amount END) AS total_planned_amount, SUM(CASE WHEN sb.type = 'OUTCOME' THEN sb.actual_amount ELSE 0 END) AS total_outcome, SUM(CASE WHEN sb.type = 'INCOME' THEN sb.actual_amount ELSE 0 END) AS total_income, SUM(CASE WHEN sb.status = 'COMPLETED' THEN 1 ELSE 0 END) AS completed_round_count, SUM(CASE WHEN sb.status = 'PENDING' THEN 1 ELSE 0 END) AS pending_round_count, COUNT(*) AS total_round_count FROM settlement_block sb JOIN block b ON b.block_id = sb.block_id JOIN step st ON st.step_id = b.step_id WHERE sb.deleted_at IS NULL GROUP BY st.project_id ) agg ON agg.project_id = p.project_id LEFT JOIN ( SELECT nb.project_id AS project_id, MIN(nb.planned_date) AS planned_date FROM ( SELECT st.project_id AS project_id, sb.round_no AS round_no, sb.planned_date AS planned_date FROM settlement_block sb JOIN block b ON b.block_id = sb.block_id JOIN step st ON st.step_id = b.step_id WHERE sb.deleted_at IS NULL AND sb.status != 'COMPLETED' ) nb JOIN ( SELECT st2.project_id AS project_id, MIN(sb2.round_no) AS min_round_no FROM settlement_block sb2 JOIN block b2 ON b2.block_id = sb2.block_id JOIN step st2 ON st2.step_id = b2.step_id WHERE sb2.deleted_at IS NULL AND sb2.status != 'COMPLETED' GROUP BY st2.project_id ) mr ON mr.project_id = nb.project_id AND mr.min_round_no = nb.round_no GROUP BY nb.project_id ) nxt ON nxt.project_id = p.project_id WHERE p.deleted_at IS NULL AND p.company_id = #{companyId} AND p.client_name = #{client}
AND p.status NOT IN ('COMPLETED', 'CLOSED') AND nxt.planned_date >= #{startDate} AND nxt.planned_date <= #{endDate}
ORDER BY (COALESCE(agg.total_income, 0) - COALESCE(agg.total_outcome, 0)) DESC, p.project_id DESC
ORDER BY nxt.planned_date IS NULL, nxt.planned_date ASC, p.project_id ASC
LIMIT #{size} OFFSET #{offset}

SELECT EXISTS (
SELECT 1 FROM project WHERE project_id = #{projectId} AND deleted_at IS NULL AND company_id = #{companyId}
)
